        reward = -action.norm(p=2)
    elif reward_type == 'reward_and_log_prob':
        reward = -action.norm(p=2)
        log_prob = torch.log_prob(action, torch.distributions.Normal(0., 1.))
        log_prob = log_prob.mean(-1)
        return reward, log_prob
    else:
        raise ValueError("Unknown reward type.")

