def reward_function(self, action):
    action = torch.tensor(action, device=self.device)
    drone_move = action @ self.drone_move_directions
    self.drone_pos += drone_move

    if self.drone_pos.norm() > self.max_pos:
        reward = -1.0
    elif self.energy_level <= 0.0:
        reward = -1.0
    elif self.drone_pos.norm() < self.package_pos.norm():
        reward = -1.0 * (self.energy_level - 0.9)
    elif self.drone_pos.norm() == self.package_pos.norm():
        reward = 0.0
    else:
        reward = 1.0 * (self.energy_level - 0.9)

    self.energy_level -= 0.1
    return reward
